layout(std140) uniform ubVSMaterial
    {
        #if defined( USE_UV0 )
            vec4 uv0OffsetScale;
            float uv0Rotate;
            float uv0UnusedA;
            float uv0UnusedB;
            float uv0UnusedC;
        #endif

        #if defined( USE_UV1 )
            vec4 uv1OffsetScale;
            float uv1Rotate;
            float uv1UnusedA;
            float uv1UnusedB;
            float uv1UnusedC;
        #endif
    };
#endif

#if defined( USE_UV0 )
	out highp vec2 vUv;
#endif

#if defined( USE_UV1 )
	out highp vec2 vUv2;
#endif

#if defined( USE_WORLD_POSITION )
	out vec3 vWorldPosition;
    uniform mat4 modelMatrix;
#endif

#if defined( USE_SSR )
    out highp mat4 projMatrix;
#endif

void main()
{
    #if defined( USE_UV0 )
        applyUVOperator( uv, uv0OffsetScale, uv0Rotate, vUv );
    #endif

    #if defined( USE_UV1 )
        applyUVOperator( uv2, uv1OffsetScale, uv1Rotate, vUv2 );
    #endif

    // DO NOT COMPUTE NORMAL MATRIX PER VERTEX IN SHADER WITH LOW PRECISION VARIABLES (ex: mobile)
	vec3 objectNormal = normal;
	vNormal = normalize( normalMatrix * objectNormal );

	vec4 mvPosition = modelViewMatrix * vec4( position, 1.0 );
	gl_Position = projectionMatrix * mvPosition;

    #if defined( USE_SSR )
        projMatrix = projectionMatrix;
    #endif

    vViewPosition = -mvPosition.xyz;

    #if defined( USE_WORLD_POSITION )
        vec4 worldPosition = modelMatrix * vec4( position, 1.0 );
        vWorldPosition = worldPosition.xyz;
    #endif
}

