// http://en.wikibooks.org/wiki/GLSL_Programming/Applying_Matrix_Transformations
highp vec3 inverseTransformDirection( in highp vec3 normal, in highp mat4 matrix ) {
    highp vec4 custoNormal = vec4( normal, 0.0 );
	return normalize( ( custoNormal * matrix ).xyz );
}
vec3 projectOnPlane(in vec3 point, in vec3 pointOnPlane, in vec3 planeNormal) {
	float distance = dot( planeNormal, point-pointOnPlane );
	return point - distance * planeNormal;
}
float sideOfPlane( in vec3 point, in vec3 pointOnPlane, in vec3 planeNormal ) {
	return sign( dot( point - pointOnPlane, planeNormal ) );
}
vec3 linePlaneIntersect( in vec3 pointOnLine, in vec3 lineDirection, in vec3 pointOnPlane, in vec3 planeNormal ) {
	return pointOnLine + lineDirection * ( dot( planeNormal, pointOnPlane - pointOnLine ) / dot( planeNormal, lineDirection ) );
}
float calcLightAttenuation( in float lightDistance, in  float cutoffDistance, in float decayExponent )
{
	if ( decayExponent > 0.0 ) {
	  return pow( saturate( 1.0 - lightDistance / cutoffDistance ), decayExponent );
	}
	return 1.0;
}
// Moving Frostbite to PBR
float smoothDistanceAtt ( in float sqrDist , in float invSqrAttRadius )
{
    float factor = sqrDist * invSqrAttRadius ;
    float smoothFactor = saturate (1.0 - factor * factor );
    return smoothFactor * smoothFactor;
}
float getDistanceAttenuation ( in float sqrDist , in float invSqrAttRadius, in float offset )
{
    float attenuation = 1.0 / ( sqrDist + offset );
    attenuation *= smoothDistanceAtt ( sqrDist , invSqrAttRadius );
    return attenuation ;
}
float getAngleAttenuation( in vec3 worldLightVector, in vec3 worldLightDirection, in vec2 lightAngleScaleAndOffset)
{
    float cd = dot ( worldLightDirection , worldLightVector );
    float attenuation = saturate ( cd * lightAngleScaleAndOffset.x + lightAngleScaleAndOffset.y ) ;

    // smooth the transition
    attenuation *= attenuation;
    attenuation *= attenuation;

    return attenuation ;
}

vec3 inputToLinear( in vec3 a ) {
#if defined( GAMMA_INPUT )
	return pow( a, vec3( float( GAMMA_FACTOR ) ) );
#else
