                vec2 base_uv;
                base_uv.x = floor(uv.x + 0.5);
                base_uv.y = floor(uv.y + 0.5);

                float s = (uv.x + 0.5 - base_uv.x);
                float t = (uv.y + 0.5 - base_uv.y);

                float uw0 = (4.0 - 3.0 * s);
                float uw1 = 7.0;
                float uw2 = (1.0 + 3.0 * s);

                float u0 = (3.0 - 2.0 * s) / uw0 - 2.0;
                float u1 = (3.0 + s) / uw1;
                float u2 = s / uw2 + 2.0;

                float vw0 = (4.0 - 3.0 * t);
                float vw1 = 7.0;
                float vw2 = (1.0 + 3.0 * t);

                float v0 = (3.0 - 2.0 * t) / vw0 - 2.0;
                float v1 = (3.0 + t) / vw1;
                float v2 = t / vw2 + 2.0;

