                float u1 = (3.0 + s) / uw1;
                float u2 = s / uw2 + 2.0;

                float vw0 = (4.0 - 3.0 * t);
                float vw1 = 7.0;
                float vw2 = (1.0 + 3.0 * t);

                float v0 = (3.0 - 2.0 * t) / vw0 - 2.0;
                float v1 = (3.0 + t) / vw1;
