//reflectVec is the one used for the sky and not SSR
vec3 computeSSR(vec3 viewPosition, vec3 normal, vec3 reflectVec )
{
	// Ray origin (view space)
	vec4 positionFrom = vec4( -viewPosition, 1.0 ); 

	// Reflected direction in view space
	vec3 incident = normalize( positionFrom.xyz );
	vec3 pivot = normalize( reflect(incident, normal) );

	// Ray endpoint
	vec4 startFrag = projMatrix * positionFrom;
	startFrag.xyz /= startFrag.w;// clip space
	vec2 startUV =  startFrag.xy * 0.5 + 0.5; // texture space
	float startLinearDepth = linearizeDepth(texture( previousDepth, startUV ).x);

	float maxDistance = mix(SSRMaxDistance / 7.0, SSRMaxDistance, clamp(startLinearDepth * 10.0, 0.0, 1.0));
	if( pivot.z > 0.0)
	{
		float maxAllowedDist = (-cameraNear * 0.99 - positionFrom.z) / max(pivot.z, 1e-4);
		maxDistance = min(maxDistance, maxAllowedDist);
	}



	float hit = 0.0;
	vec2 hitUV = vec2(0.0);
	float hitD = 1.0;

	float dStart = float( SSR_STEP );

	for (float d = dStart; d <= 1.0; d += float(SSR_STEP))
    {
        // Reproject each step — no UV lerp, avoids perspective distortion
        vec4 currentView = vec4(positionFrom.xyz + pivot * maxDistance * d, 1.0);
        vec4 currentFrag = projMatrix * currentView;
		if ( currentFrag.w <= 0.0 ) break;

        // Skip if behind camera
        if (currentFrag.w <= 0.0) break;

        currentFrag.xyz /= currentFrag.w;
		if ( currentFrag.x < -1.0 || currentFrag.x > 1.0 ||
         currentFrag.y < -1.0 || currentFrag.y > 1.0 ) break;

        // Skip if outside frustum
        if (abs(currentFrag.x) > 1.0 || abs(currentFrag.y) > 1.0) continue;

        vec2  currentUV    = currentFrag.xy * 0.5 + 0.5;
        float sampledDepth = linearizeDepth(texture(previousDepth, currentUV).x);
        float rayDepth     = linearizeDepth(currentFrag.z * 0.5 + 0.5);
        float diff         = rayDepth - sampledDepth;

        if (diff > 1e-4 && diff < SSRThickness)
        {
            // Binary search refinement
            float dMin = d - float(SSR_STEP);
            float dMax = d;

            for (int r = 0; r < 4; r++)
            {
                float dMid       = (dMin + dMax) * 0.5;
                vec4  midView    = vec4(positionFrom.xyz + pivot * maxDistance * dMid, 1.0);
                vec4  midFrag    = projMatrix * midView;
                midFrag.xyz     /= midFrag.w;
                vec2  midUV      = midFrag.xy * 0.5 + 0.5;
                float midSampled = linearizeDepth(texture(previousDepth, midUV).x);
                float midRay     = linearizeDepth(midFrag.z * 0.5 + 0.5);
                float midDiff    = midRay - midSampled;

                if (midDiff > 1e-4 && midDiff < SSRThickness)
                {
                    dMax  = dMid;
                    hitUV = midUV;
                }
                else
                {
                    dMin = dMid;
                }
            }


            // Cleaner version of the above:
            float dFinal     = (dMin + dMax) * 0.5;
            vec4  finalView  = vec4(positionFrom.xyz + pivot * maxDistance * dFinal, 1.0);
            vec4  finalFrag  = projMatrix * finalView;
            finalFrag.xyz   /= finalFrag.w;
            hitUV            = finalFrag.xy * 0.5 + 0.5;
            hitD             = dFinal;
            hit              = 1.0;
            break;
        }
    }

	vec3 sky = computeSky( reflectVec );
	vec3 reflectedColor;
	if ( hit > 0.5 )
	{
		reflectedColor = samplePreviousColor( hitUV );
	}
	else
	{
		reflectedColor = sky;
	}

	float edgeFade = smoothstep(0.4, 0.5, max(abs( hitUV.x - 0.5 ), abs( hitUV.y - 0.5 )));
	float distFade = smoothstep(0.5, 1.0, hitD);
	float fade = hit > 0.5 ? max( edgeFade, distFade ) : 0.0;
	reflectedColor = mix( reflectedColor, sky, fade * hit );

	return clamp( reflectedColor, 0.0, 1.0 );
}

