        // use just first frustum (for cascades)
        bvec4 inFrustumVec = bvec4 ( shadowCoords.x >= 0.0, shadowCoords.x <= 1.0, shadowCoords.y >= 0.0, shadowCoords.y <= 1.0 );

        return all( inFrustumVec );
