                sum += uw1 * vw0 * texture2DCompare( shadowMap, base_uv + vec2( u1, v0 ) * shadowMapSizeInv, shadowCoord.z );
                sum += uw2 * vw0 * texture2DCompare( shadowMap, base_uv + vec2( u2, v0 ) * shadowMapSizeInv, shadowCoord.z );

