        + iSH[ 4 ].rgb * ( n.y * n.x )
        + iSH[ 5 ].rgb * ( n.y * n.z )
        + iSH[ 6 ].rgb * ( 3.0 * n.z * n.z - 1.0 )
        + iSH[ 7 ].rgb * ( n.z * n.x )
        + iSH[ 8 ].rgb * ( n.x * n.x - n.y * n.y );
    #else
        return vec3( 1.0 );
    #endif
}

// https://www.shadertoy.com/view/MslGR8
vec3 ScreenSpaceDither( vec2 vScreenPos )
{
    vec3 vDither = vec3( dot( vec2( 171.0, 231.0 ), vScreenPos.xy ) );
    vDither.rgb = fract( vDither.rgb / vec3( 103.0, 71.0, 97.0 ) );
    return vDither.rgb / 255.0;
}

vec3 dither ( in vec3 inputColor )
{
    #if defined( USE_DITHERING )
        return inputColor + ScreenSpaceDither( gl_FragCoord.xy );
    #else
        return inputColor;
    #endif

}

float getLuminance( in vec3 iColor )
{
	return ( 0.2126 * iColor.r ) + ( 0.7152 * iColor.g ) + ( 0.0722 * iColor.b );
}

void applyUVOperator( in vec2 iUv, in vec4 iOffsetScale, in float iRotate, out vec2 oUv )
{
    float x = iUv.x / iOffsetScale.z - iOffsetScale.x;
    float y = iUv.y / iOffsetScale.w - iOffsetScale.y;

	float c = cos( iRotate );
    float s = sin( iRotate );

    oUv.x = x * c - y * s;
    oUv.y = y * c + x * s;
}

#define A (0.15)
#define B (0.50)
#define C (0.10)
#define D (0.20)
#define E (0.02)
#define F (0.30)

vec3 Uncharted2Tonemap( in vec3 x)
{
    vec3 denominator = saturateFP16( ( x * ( A * x + B ) + D * F ) );
    return ( ( x * ( A * x + C * B ) + D * E ) / denominator ) - E / F;
}

vec3 toneMap( in vec3 originalColor )
{
    #if defined( USE_TONE_MAPPING ) //uncharted2_filmic
        const float exposureBias = 3.0;
        const vec3 whiteScale = vec3( 1.3790642466494378 );   // 1.0 / Uncharted2Tonemap( vec3( 11.2 ) );
        vec3 temp = exposureBias * Uncharted2Tonemap( originalColor );
        return temp * whiteScale;
    #else
        return originalColor;
    #endif
}


// Our version -> already in normalized space using a [-16, 16] exponent
vec3 rgbeToLinear( in vec4 colorData )
{
    highp float exponent = exp2( colorData.a * 32.0 - 16.0 );
    highp vec3 hdrColor = colorData.rgb * exponent;

    return hdrColor;
}

vec3 rgbeStdToLinear( in vec4 colorData )
{
    highp float exponent = exp2( colorData.a * 256.0 - 128.0 );
    highp vec3 hdrColor = colorData.rgb * exponent;

    return hdrColor;
}

vec3 rgbmToLinear( in vec4 colorData )
{
    vec3 prefilteredColor = colorData.rgb * ( 16.0 * colorData.a );
    return prefilteredColor * prefilteredColor;
}

// lots of tonemaps base on https://64.github.io/tonemapping/

vec3 reinhard( in vec3 color )
{
    return color / (1.0 + color);
}

vec3 extendedReinhard( in vec3 color, in float range)
{
    vec3 numerator = color * (1.0 + (color / vec3( range * range)));
    return numerator / (1.0 + color);
}

vec3 changeLuminance( in vec3 color, in float luminance )
{
    float pLum = getLuminance( color );
    return color * ( luminance / pLum );
}

vec3 reinhardExtendedLuminance( in vec3 color, in float range )
{
    float pLum = getLuminance( color );
    float numerator = pLum * (1.0 + (pLum / ( range * range)));
    float nLum = numerator / (1.0 + pLum);
    return changeLuminance( color, nLum );
}

vec3 reinhardJodie(vec3 color)
{
    float l = getLuminance(color);
    vec3 tonemapped = color / (1.0 + color);
    return mix( color / (1.0 + l), tonemapped, tonemapped);
}

vec3 acesApprox( in vec3 color )
{
    color *= 0.6;
    float a = 2.51;
    float b = 0.03;
    float c = 2.43;
    float d = 0.59;
    float e = 0.14;
    return clamp((color * (a * color + b)) / (color * (c * color + d) + e), 0.0, 1.0);
}


