                sum += uw2 * vw0 * texture2DCompare( shadowMap, layer, base_uv + vec2( u2, v0 ) * shadowMapSizeInv, shadowCoord.z );

                sum += uw0 * vw1 * texture2DCompare( shadowMap, layer, base_uv + vec2( u0, v1 ) * shadowMapSizeInv, shadowCoord.z );
                sum += uw1 * vw1 * texture2DCompare( shadowMap, layer, base_uv + vec2( u1, v1 ) * shadowMapSizeInv, shadowCoord.z );
                sum += uw2 * vw1 * texture2DCompare( shadowMap, layer, base_uv + vec2( u2, v1 ) * shadowMapSizeInv, shadowCoord.z );

                sum += uw0 * vw2 * texture2DCompare( shadowMap, layer, base_uv + vec2( u0, v2 ) * shadowMapSizeInv, shadowCoord.z );
                sum += uw1 * vw2 * texture2DCompare( shadowMap, layer, base_uv + vec2( u1, v2 ) * shadowMapSizeInv, shadowCoord.z );
                sum += uw2 * vw2 * texture2DCompare( shadowMap, layer, base_uv + vec2( u2, v2 ) * shadowMapSizeInv, shadowCoord.z );

                sum *= 1.0 / 144.0;

                return 1.0 - sum;
            }

