                float dx1 = + texelSize.x * pcfSoftShadowRadius;
                float dy1 = + texelSize.y * pcfSoftShadowRadius;

                return 1.0 - (
                texture2DShadowLerp( shadowMap, layer, shadowMapSize, shadowCoord.xy + vec2( dx0, dy0 ), shadowCoord.z ) +
                texture2DShadowLerp( shadowMap, layer, shadowMapSize, shadowCoord.xy + vec2( 0.0, dy0 ), shadowCoord.z ) +
                texture2DShadowLerp( shadowMap, layer, shadowMapSize, shadowCoord.xy + vec2( dx1, dy0 ), shadowCoord.z ) +
                texture2DShadowLerp( shadowMap, layer, shadowMapSize, shadowCoord.xy + vec2( dx0, 0.0 ), shadowCoord.z ) +
                texture2DShadowLerp( shadowMap, layer, shadowMapSize, shadowCoord.xy, shadowCoord.z )                    +
                texture2DShadowLerp( shadowMap, layer, shadowMapSize, shadowCoord.xy + vec2( dx1, 0.0 ), shadowCoord.z ) +
                texture2DShadowLerp( shadowMap, layer, shadowMapSize, shadowCoord.xy + vec2( dx0, dy1 ), shadowCoord.z ) +
                texture2DShadowLerp( shadowMap, layer, shadowMapSize, shadowCoord.xy + vec2( 0.0, dy1 ), shadowCoord.z ) +
                texture2DShadowLerp( shadowMap, layer, shadowMapSize, shadowCoord.xy + vec2( dx1, dy1 ), shadowCoord.z )
                ) * ( 1.0 / 9.0 );
            }

        #endif

        #if defined( USE_SHADOWMAP_TYPE_PCF_VOGEL )

            float computeShadowContribVogelDisk( in vec2 shadowMapSize, in float radius, in sampler2DArrayShadow shadowMap, in int layer, in vec3 shadowCoord )
            {
                float seed = interleavedGradientNoise( shadowCoord.xy ) * 2.0 * PI;
                float shadowContrib = 0.0;
                for ( float i = 0.0; i < DYNAMIC_SHADOWMAP_SAMPLE_COUNT; i++ )
                {
                    shadowContrib += texture2DCompare( shadowMap, layer, vogelDiskSample( i, DYNAMIC_SHADOWMAP_SAMPLE_COUNT, seed ) * radius / shadowMapSize + shadowCoord.xy, shadowCoord.z );
                }
                return 1.0 - shadowContrib * ( 1.0 / DYNAMIC_SHADOWMAP_SAMPLE_COUNT );
            }

        #endif

        #if defined( USE_SHADOWMAP_TYPE_PCF_WITNESS )

            float computeShadowContribPCFWitness( in vec2 shadowMapSize, in sampler2DArrayShadow shadowMap, in int layer, in vec3 shadowCoord )
            {
                vec2 uv = shadowCoord.xy * shadowMapSize; // 1 unit - 1 texel

                vec2 shadowMapSizeInv = 1.0 / shadowMapSize;

                vec2 base_uv;
                base_uv.x = floor(uv.x + 0.5);
                base_uv.y = floor(uv.y + 0.5);

                float s = (uv.x + 0.5 - base_uv.x);
                float t = (uv.y + 0.5 - base_uv.y);

                float uw0 = (4.0 - 3.0 * s);
                float uw1 = 7.0;
                float uw2 = (1.0 + 3.0 * s);

                float u0 = (3.0 - 2.0 * s) / uw0 - 2.0;
                float u1 = (3.0 + s) / uw1;
                float u2 = s / uw2 + 2.0;

                float vw0 = (4.0 - 3.0 * t);
                float vw1 = 7.0;
                float vw2 = (1.0 + 3.0 * t);

                float v0 = (3.0 - 2.0 * t) / vw0 - 2.0;
                float v1 = (3.0 + t) / vw1;
                float v2 = t / vw2 + 2.0;

                base_uv -= vec2(0.5, 0.5);
                base_uv *= shadowMapSizeInv;

                float sum = 0.0;

                sum += uw0 * vw0 * texture2DCompare( shadowMap, layer, base_uv + vec2( u0, v0 ) * shadowMapSizeInv, shadowCoord.z );
                sum += uw1 * vw0 * texture2DCompare( shadowMap, layer, base_uv + vec2( u1, v0 ) * shadowMapSizeInv, shadowCoord.z );
                sum += uw2 * vw0 * texture2DCompare( shadowMap, layer, base_uv + vec2( u2, v0 ) * shadowMapSizeInv, shadowCoord.z );

                sum += uw0 * vw1 * texture2DCompare( shadowMap, layer, base_uv + vec2( u0, v1 ) * shadowMapSizeInv, shadowCoord.z );
                sum += uw1 * vw1 * texture2DCompare( shadowMap, layer, base_uv + vec2( u1, v1 ) * shadowMapSizeInv, shadowCoord.z );
                sum += uw2 * vw1 * texture2DCompare( shadowMap, layer, base_uv + vec2( u2, v1 ) * shadowMapSizeInv, shadowCoord.z );

                sum += uw0 * vw2 * texture2DCompare( shadowMap, layer, base_uv + vec2( u0, v2 ) * shadowMapSizeInv, shadowCoord.z );
                sum += uw1 * vw2 * texture2DCompare( shadowMap, layer, base_uv + vec2( u1, v2 ) * shadowMapSizeInv, shadowCoord.z );
                sum += uw2 * vw2 * texture2DCompare( shadowMap, layer, base_uv + vec2( u2, v2 ) * shadowMapSizeInv, shadowCoord.z );

                sum *= 1.0 / 144.0;

                return 1.0 - sum;
            }

        #endif

        float computeDynamicShadow( in float fixedBias, in float normalBias, in float radius, in vec3 worldNormal, in vec3 worldPosition, in highp mat4 shadowMatrix,
            in vec3 shadowDirLightDirection, in sampler2DArrayShadow shadowMaps, int layer )
        {
            vec4 shadowCoords ;
            if( !computeShadowCoords( fixedBias, normalBias, worldNormal, worldPosition, shadowMatrix, shadowCoords ) )
            {
                return 0.0;
            }

            // Dot product between world normal and world shadow light direction
            float shadowDotProduct = dot( worldNormal, shadowDirLightDirection );

            float shadowContrib = 0.0;
            // Face to shadow light
            if( shadowDotProduct > 0.001  )
            {
                #if ( DYNAMIC_SHADOWMAP_TYPE == SHADOWMAP_TYPE_PCF )
                    shadowContrib = computeShadowContribPCF( vec2( DYNAMIC_SHADOWMAP_SIZE ), radius, shadowMaps, layer, shadowCoords.xyz );
                #elif ( DYNAMIC_SHADOWMAP_TYPE == SHADOWMAP_TYPE_PCF_SOFT )
                    shadowContrib = computeShadowContribPCFSoft( vec2( DYNAMIC_SHADOWMAP_SIZE ), shadowMaps, layer, shadowCoords.xyz );
                #elif ( DYNAMIC_SHADOWMAP_TYPE == SHADOWMAP_TYPE_PCF_VOGEL )
                    shadowContrib = computeShadowContribVogelDisk( vec2( DYNAMIC_SHADOWMAP_SIZE ), radius, shadowMaps, layer, shadowCoords.xyz );
                #elif ( DYNAMIC_SHADOWMAP_TYPE == SHADOWMAP_TYPE_PCF_WITNESS )
                    shadowContrib = computeShadowContribPCFWitness( vec2( DYNAMIC_SHADOWMAP_SIZE ), shadowMaps, layer, shadowCoords.xyz );
                #else
                    shadowContrib = computeShadowContribBasic( shadowMaps, layer, shadowCoords.xyz );
                #endif
            }
            return shadowContrib;
        }

    #endif

