	// Per-Pixel Tangent Space Normal Mapping
	// http://hacksoflife.blogspot.ch/2009/11/per-pixel-tangent-space-normal-mapping.html

	vec3 perturbNormal2Arb( highp vec3 eye_pos, highp vec3 surf_norm )
    {
        highp vec3 q0 = dFdx( eye_pos.xyz );
        highp vec3 q1 = dFdy( eye_pos.xyz );
        highp vec2 st0 = dFdx( vUv.st );
        highp vec2 st1 = dFdy( vUv.st );

        vec3 S = normalize( q0 * st1.t - q1 * st0.t );
        vec3 T = normalize( -q0 * st1.s + q1 * st0.s );

        vec3 mapN = texture( normalMap, vUv ).xyz * 2.0 - 1.0;
        mapN.xy = normalScale * mapN.xy;
        mat3 tsn = mat3( S, T, surf_norm );

        return normalize( tsn * mapN );
	}
